cat > /tmp/pw/interact.mjs <<'EOF'
import { chromium } from 'playwright';
const browser = await chromium.launch({ args: ['--no-sandbox','--disable-dev-shm-usage','--disable-gpu'] });
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
const errors = [];
page.on('pageerror', e => errors.push('pageerror: ' + e.message));
page.on('console', m => { if (m.type() === 'error' || m.type() === 'warning') errors.push(m.type() + ': ' + m.text()); });
await page.goto('http://localhost:5199/');
await page.waitForSelector('table');
const bar = () => page.locator('.orders-table__selection-bar').innerText();
const headers = () => page.locator('thead th').allInnerTexts();
const selectedIds = () => page.locator('tr.orders-table__row_selected td:nth-child(2)').allInnerTexts();

// 1. click row
await page.getByText('#10479').click();
console.log('after click:', await bar(), await selectedIds());
// 2. shift-click range (across group boundary)
await page.getByText('#10470').click({ modifiers: ['Shift'] });
console.log('after shift:', await bar(), await selectedIds());
// 3. click again toggles off
await page.getByText('#10470').click();
console.log('after toggle off:', await bar());
// 4. group checkbox for "Новый"
const newGroup = page.locator('tr.orders-table__group-row').first();
await newGroup.locator('input[type=checkbox]').check();
console.log('after group check:', await bar(), await selectedIds());
// 5. checkbox in a row
await page.locator('tbody tr').filter({ hasText: '#10464' }).locator('input[type=checkbox]').click();
console.log('after row checkbox:', await bar());
await page.screenshot({ path: '/tmp/pw/2-selected.png' });
// 6. header select all
await page.locator('thead input[type=checkbox]').click();
console.log('after select all:', await bar());
await page.locator('thead input[type=checkbox]').click();
console.log('after unselect all:', await bar());
// 7. collapse group via click on group row
const before = await page.locator('tbody tr').count();
await page.locator('tr.orders-table__group-row').nth(1).click();
console.log('rows before/after collapse:', before, await page.locator('tbody tr').count());
await page.getByRole('button', { name: /Свернуть все группы/ }).click();
console.log('rows after collapse all:', await page.locator('tbody tr').count());
await page.screenshot({ path: '/tmp/pw/3-collapsed.png' });
await page.getByRole('button', { name: /Развернуть все группы/ }).click();
console.log('rows after expand all:', await page.locator('tbody tr').count());
// 8. drag column "Город" before "Клиент"
console.log('headers before:', (await headers()).join(' | '));
const src = await page.locator('thead th', { hasText: 'Город' }).boundingBox();
const dst = await page.locator('thead th', { hasText: 'Клиент' }).boundingBox();
await page.mouse.move(src.x + src.width / 2, src.y + src.height / 2);
await page.mouse.down();
for (let i = 1; i <= 20; i++) {
  await page.mouse.move(src.x + src.width / 2 + ((dst.x + 10) - (src.x + src.width / 2)) * i / 20, src.y + src.height / 2);
  await page.waitForTimeout(16);
}
await page.screenshot({ path: '/tmp/pw/4-dragging.png' });
await page.mouse.up();
await page.waitForTimeout(200);
console.log('headers after drag:', (await headers()).join(' | '));
// 9. toggle grouping off
await page.getByText('Группировать по статусу').click();
console.log('group rows when ungrouped:', await page.locator('tr.orders-table__group-row').count(), 'rows:', await page.locator('tbody tr').count());
console.log('first rows:', (await page.locator('tbody tr td:nth-child(2)').allInnerTexts()).slice(0, 4));
await page.screenshot({ path: '/tmp/pw/5-ungrouped.png' });
// 10. reset order
await page.getByRole('button', { name: 'Сбросить порядок колонок' }).click();
console.log('headers after reset:', (await headers()).join(' | '));
// 11. collapse sidebar
const asideW = async () => (await page.locator('.gn-aside-header__aside').boundingBox())?.width;
console.log('aside width before:', await asideW());
await page.getByRole('button', { name: 'Свернуть меню' }).click();
await page.waitForTimeout(400);
console.log('aside width after:', await asideW());
await page.getByRole('button', { name: 'Пользователи' }).hover();
await page.waitForTimeout(500);
await page.screenshot({ path: '/tmp/pw/6-compact.png' });
await page.getByRole('button', { name: 'Пользователи' }).click().catch(async () => page.locator('.gn-composite-bar-item').nth(1).click());
console.log('title after nav:', await page.locator('h1').innerText());
await page.reload(); await page.waitForTimeout(500);
console.log('aside width after reload:', await asideW());
console.log('errors:', errors);
await browser.close();
EOF
